BEGIN;
SET search_path=public,extensions;
SELECT no_plan();
CREATE TEMP TABLE delivery_cash_baseline AS SELECT count(*) AS n FROM public.transactions;
SELECT has_function('public','save_supplier_design_instruction',ARRAY['uuid','uuid','text','text','text','jsonb','boolean'],'Versioned supplier paragraph writer exists');
INSERT INTO auth.users(id,email) SELECT ('ab100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'instructions-'||n||'@local.test' FROM generate_series(1,3)n;
INSERT INTO public.users(id,auth_id,username,role,name) SELECT ('ab100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('ab100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'instruction_test_'||n,(ARRAY['admin','designer','designer'])[n],'Instruction test '||n FROM generate_series(1,3)n;
INSERT INTO public.suppliers(id,name,phone) VALUES('ab100000-0000-4000-8000-000000000010','QA Secret Supplier','01000000001');
INSERT INTO public.doctors(id,name,phone,address,doctor_code,representative_name) VALUES('ab100000-0000-4000-8000-000000000011','Instruction doctor','01000000000','QA','INS-QA','QA');
INSERT INTO public.orders(id,case_id,doctor_id,patient_name,items,total_price,cost,shade,production_status,delivery_date,workflow_type,designer_id,supplier_id)
VALUES('ab100000-0000-4000-8000-000000000012','INS-CASE','ab100000-0000-4000-8000-000000000011','QA','[]',100,10,'A1','designing',current_date,'split','ab100000-0000-4000-8000-000000000002','ab100000-0000-4000-8000-000000000010');
SELECT set_config('request.jwt.claim.sub','ab100000-0000-4000-8000-000000000001',true);
SELECT public.save_supplier_design_text('ab100000-0000-4000-8000-000000000010','ab100000-0000-4000-8000-000000000020','Technical text only');
SELECT public.set_design_qc_enabled(true,'Choice tests');
SELECT set_config('request.jwt.claim.sub','ab100000-0000-4000-8000-000000000002',true);
SELECT lives_ok($$SELECT public.submit_design_delivery('ab100000-0000-4000-8000-000000000012','ab100000-0000-4000-8000-000000000030','link','https://drive.google.com/file/d/example','No preview')$$,'Link-only delivery needs no ZIP');
SELECT is((SELECT execution_path FROM public.design_revisions WHERE id='ab100000-0000-4000-8000-000000000030'),NULL::text,'External reference is not presented as immutable uploaded bytes');
SELECT is(public.get_design_delivery_asset('ab100000-0000-4000-8000-000000000012',NULL)->>'url','https://drive.google.com/file/d/example','Authorized execution resolves the saved link');
SELECT throws_ok($$SELECT public.release_design_revision('ab100000-0000-4000-8000-000000000012')$$,'42501','Release role required','Designer cannot release their own revision');
SELECT throws_ok($$SELECT public.save_supplier_design_text('ab100000-0000-4000-8000-000000000010',gen_random_uuid(),'Forged')$$,'42501','Admin role required','Simple text remains admin-only');
SELECT set_config('request.jwt.claim.sub','ab100000-0000-4000-8000-000000000001',true);
SELECT throws_ok($$SELECT public.release_design_revision('ab100000-0000-4000-8000-000000000012')$$,'23514','Design QC approval or permitted bypass required','Link submissions still require QC when enabled');
SELECT public.decide_design_revision('ab100000-0000-4000-8000-000000000030',gen_random_uuid(),'approved','');
SELECT public.save_supplier_design_text('ab100000-0000-4000-8000-000000000010','ab100000-0000-4000-8000-000000000021','New technical text');
SELECT is(public.get_order_design_instruction('ab100000-0000-4000-8000-000000000012','ab100000-0000-4000-8000-000000000030')->>'paragraph','Technical text only','Link submission keeps prior instruction version');
SELECT ok(public.design_qc_gate_passes('ab100000-0000-4000-8000-000000000030'),'Text-only update preserves approval');
SELECT lives_ok($$SELECT public.release_design_revision('ab100000-0000-4000-8000-000000000012')$$,'Approved link can be released');
INSERT INTO public.production_jobs(id,order_id,route_id,round_no,unit_count,status) SELECT 'ab100000-0000-4000-8000-000000000051','ab100000-0000-4000-8000-000000000012',id,99,1,'queued' FROM public.production_routes ORDER BY created_at LIMIT 1;
INSERT INTO public.production_stage_runs(id,job_id,stage_id,seq,execution,status,units_in) SELECT 'ab100000-0000-4000-8000-000000000052','ab100000-0000-4000-8000-000000000051',id,99,'internal','pending',1 FROM public.production_stages WHERE code<>'design' ORDER BY code LIMIT 1;
UPDATE public.production_stage_runs SET status='in_progress' WHERE id='ab100000-0000-4000-8000-000000000052';
INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('design-qc-files','ab100000-0000-4000-8000-000000000012/ab100000-0000-4000-8000-000000000031/execution.zip','{"size":100,"eTag":"file-choice","mimetype":"application/zip"}');
SELECT lives_ok($$SELECT public.submit_design_delivery('ab100000-0000-4000-8000-000000000012','ab100000-0000-4000-8000-000000000031','file',NULL,'No preview')$$,'Uploaded execution needs no external link');
SELECT is((SELECT execution_url FROM public.design_revisions WHERE id='ab100000-0000-4000-8000-000000000031'),NULL::text,'Uploaded delivery does not invent a URL');
SELECT is(public.get_design_delivery_asset('ab100000-0000-4000-8000-000000000012',NULL)->>'path','ab100000-0000-4000-8000-000000000012/ab100000-0000-4000-8000-000000000031/execution.zip','Execution resolves private uploaded source');
SELECT ok(NOT coalesce(public.design_qc_gate_passes('ab100000-0000-4000-8000-000000000031'),false),'Changed execution invalidates old approval');
SELECT is(public.get_design_delivery_asset('ab100000-0000-4000-8000-000000000012','ab100000-0000-4000-8000-000000000052')->>'url','https://drive.google.com/file/d/example','Running stage keeps its exact link snapshot after a newer uploaded revision');
SELECT throws_ok($$SELECT public.get_design_delivery_asset('ab100000-0000-4000-8000-000000000012','ab100000-0000-4000-8000-000000000099')$$,'42501','Design access denied','Stage resolver rejects unrelated or missing stages');
SELECT throws_ok($$SELECT public.submit_design_delivery('ab100000-0000-4000-8000-000000000012',gen_random_uuid(),'link','javascript:alert(1)','No preview')$$,'22023','HTTPS execution link required','Unsafe reference rejected');
SELECT throws_ok($$SELECT public.submit_design_delivery('ab100000-0000-4000-8000-000000000012',gen_random_uuid(),'file',NULL,'No preview')$$,'22023','Immutable execution ZIP required','Missing upload rejected');
SELECT public.decide_design_revision('ab100000-0000-4000-8000-000000000031',gen_random_uuid(),'approved','');
INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('design-qc-files','ab100000-0000-4000-8000-000000000012/ab100000-0000-4000-8000-000000000036/execution.zip','{"size":100,"eTag":"file-choice","mimetype":"application/zip"}');
SELECT is(public.submit_design_delivery('ab100000-0000-4000-8000-000000000012','ab100000-0000-4000-8000-000000000036','file',NULL,'No preview'),'ab100000-0000-4000-8000-000000000031'::uuid,'Reuploading identical execution bytes keeps the approved revision');
SELECT ok(public.design_qc_gate_passes('ab100000-0000-4000-8000-000000000031'),'Identical files do not invalidate approval');
SELECT public.decide_design_revision('ab100000-0000-4000-8000-000000000031',gen_random_uuid(),'rejected','Amend design');
SELECT throws_ok($$SELECT public.decide_design_revision('ab100000-0000-4000-8000-000000000031',gen_random_uuid(),'bypassed','urgent')$$,'23514','Rejected execution files cannot be bypassed','Rejected file bypass remains forbidden');
SELECT throws_ok($$SELECT public.submit_design_delivery('ab100000-0000-4000-8000-000000000012',gen_random_uuid(),'file','https://example.test/duplicate','No preview')$$,'22023','Choose one execution source','New delivery API rejects simultaneous sources');
SELECT public.submit_design_delivery('ab100000-0000-4000-8000-000000000012','ab100000-0000-4000-8000-000000000032','link','https://drive.google.com/file/d/example','No preview');
SELECT ok(NOT coalesce(public.design_qc_gate_passes('ab100000-0000-4000-8000-000000000032'),false),'Explicit resubmission of a link requires fresh review even for the same URL');
SELECT public.decide_design_revision('ab100000-0000-4000-8000-000000000032',gen_random_uuid(),'rejected','Amend external file');
SELECT public.submit_design_delivery('ab100000-0000-4000-8000-000000000012','ab100000-0000-4000-8000-000000000033','link','https://drive.google.com/file/d/example','No preview');
SELECT throws_ok($$SELECT public.decide_design_revision('ab100000-0000-4000-8000-000000000033',gen_random_uuid(),'bypassed','same link')$$,'23514','Rejected execution files cannot be bypassed','Resubmitting rejected external reference cannot bypass rejection');
SELECT is((SELECT count(*) FROM public.transactions),(SELECT n FROM delivery_cash_baseline),'Delivery source choices do not post cash');
UPDATE public.orders SET is_archived=true WHERE id='ab100000-0000-4000-8000-000000000012';
SELECT throws_ok($$SELECT public.submit_design_delivery('ab100000-0000-4000-8000-000000000012',gen_random_uuid(),'link','https://example.test/archived','No preview')$$,'P0001','Split design is unavailable','Archived cases cannot be resubmitted through the new API');
UPDATE public.orders SET is_archived=false WHERE id='ab100000-0000-4000-8000-000000000012';
SELECT set_config('request.jwt.claim.sub','ab100000-0000-4000-8000-000000000003',true);
SELECT throws_ok($$SELECT public.get_design_delivery_asset('ab100000-0000-4000-8000-000000000012',NULL)$$,'42501','Design access denied','Unassigned designer cannot resolve source');
SELECT * FROM finish();
ROLLBACK;
